# -*- coding: utf-8 -*-
"""Build an offline-readable HTML report from recorded measurements."""
import html, json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
def read(p,default):
    f=ROOT/p
    return json.loads(f.read_text()) if f.exists() else default
t=read('results/run1/training.json',{})
e=read('results/evaluation/evaluation.json',{})
k=read('results/evaluation/kid.json',{})
v=read('results/validation.json',{})
d=read('data/manifest.json',{})
profiles=[read('results/'+p,{}) for p in ['profile_amp32.json','profile_amp64.json','profile_fp32_32.json']]
snapshots=sorted([int(p.stem.replace('ema_step','')) for p in (ROOT/'results/run1').glob('ema_step*.png')])
notes=read('results/notes.json',{'conclusion':'首轮实验记录。请结合未筛选样本网格判断质量。','next':'训练预算有限，不能把 loss 下降等同于人脸生成已经收敛。'})
color=read('results/color_diagnosis/diagnosis.json',{})
control=read('results/control_color/diagnosis.json',{})
weighted=read('results/dc_color/diagnosis.json',{})
gray=read('results/gray_evaluation/distribution.json',{})
gray_train=read('results/gray5k/training.json',{})
payload={'training':t,'evaluation':e,'kid':k,'validation':v,'data':d,'profiles':profiles,'snapshots':snapshots,'notes':notes,
         'color':color,'control':control,'weighted':weighted,'gray':gray,'gray_train':gray_train}
data_json=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')
